// Pieces of markup shared by both languages of the codex.

import { ARMY_VALUE, GOALS, WHITE, BLACK } from '../engine.js';

export const FLEURON = `<svg class="fleuron" viewBox="0 0 160 18" aria-hidden="true"><path d="M4 9h52M104 9h52" stroke="currentColor" stroke-width="1"/><path d="M80 2c-5 0-8 3-8 7s3 7 8 7 8-3 8-7-3-7-8-7zm-14 7c-3-4-7-5-10-3 3 0 5 1 6 3-1 2-3 3-6 3 3 2 7 1 10-3zm28 0c3-4 7-5 10-3-3 0-5 1-6 3 1 2 3 3 6 3-3 2-7 1-10-3z" fill="currentColor"/></svg>`;

const ROOTS = [[2, 4, 6, 8], [3, 5, 7, 9]];
const PYRAMID_ROOT = [6, 9];

// The six numbers generated by each root a, as in the Renaissance treatises.
export function rootsTable(side, L) {
  const rows = ROOTS[side].map((a) => {
    const n = [a, a * a, a * (a + 1), (a + 1) ** 2, (a + 1) * (2 * a + 1), (2 * a + 1) ** 2];
    const cells = n.map((v, i) => {
      const pyr = i === 4 && a === PYRAMID_ROOT[side];
      return `<td class="num">${pyr ? `<span class="rubric" title="${L.pyramid}">${v}▲</span>` : v}</td>`;
    }).join('');
    return `<tr><th scope="row">${a}</th>${cells}</tr>`;
  }).join('');
  return `<div class="table-wrap"><table>
    <caption class="latin">${side === WHITE ? L.white : L.black}</caption>
    <thead><tr><th>${L.root}</th><th class="num" colspan="2">${L.circles}<br><span class="math">a, a²</span></th>
    <th class="num" colspan="2">${L.triangles}<br><span class="math">a(a+1), (a+1)²</span></th>
    <th class="num" colspan="2">${L.squares}<br><span class="math">(a+1)(2a+1), (2a+1)²</span></th></tr></thead>
    <tbody>${rows}</tbody></table></div>`;
}

// One root's chain of ratios: a → a² → a(a+1) → (a+1)² → (a+1)(2a+1) → (2a+1)².
export function chain(a) {
  const n = [a, a * a, a * (a + 1), (a + 1) ** 2, (a + 1) * (2 * a + 1), (2 * a + 1) ** 2];
  const ratios = [`${a} : 1`, `${a + 1} : ${a}`, `${a + 1} : ${a}`, `${2 * a + 1} : ${a + 1}`, `${2 * a + 1} : ${a + 1}`];
  let out = `<b>${n[0]}</b>`;
  for (let i = 0; i < ratios.length; i++) out += ` <span class="ratio">${ratios[i]}</span> <b>${n[i + 1]}</b>`;
  return `<p class="chain">${out}</p>`;
}

export function goalsTable(L) {
  const rows = Object.entries(GOALS).map(([k, g]) => `<tr><th scope="row">${L[k]}</th>
    <td class="num">${g.count}</td><td class="num">${Math.round(g.share * 100)} %</td>
    <td class="num">${Math.ceil(g.share * ARMY_VALUE[BLACK])}</td><td class="num">${Math.ceil(g.share * ARMY_VALUE[WHITE])}</td></tr>`).join('');
  return `<div class="table-wrap"><table>
    <thead><tr><th>${L.length}</th><th class="num">${L.corpore}</th><th class="num">${L.share}</th>
    <th class="num">${L.bonisWhite}</th><th class="num">${L.bonisBlack}</th></tr></thead>
    <tbody>${rows}</tbody></table></div>`;
}

export { ARMY_VALUE };
